const staffing=(people=120)=>({shifts:[{shiftId:'early',name:'早班',people,personDays:people*5}],days:[{shiftId:'early',date:'2026-10-29',people}]})
function fakeSyncHost(){const winEvents=new Map(),docEvents=new Map();let interval=null,cleared=false;const win={addEventListener:(name,fn)=>winEvents.set(name,fn),removeEventListener:name=>winEvents.delete(name),setInterval:(fn,ms)=>{assert.equal(ms,15000);interval=fn;return 1},clearInterval:()=>{cleared=true}};const doc={visibilityState:'visible',addEventListener:(name,fn)=>docEvents.set(name,fn),removeEventListener:name=>docEvents.delete(name)};return {win,doc,tick:()=>interval?.(),focus:()=>winEvents.get('focus')?.(),visibility:()=>docEvents.get('visibilitychange')?.(),clean:()=>cleared&&winEvents.size===0&&docEvents.size===0}}
function installSyncHost(){const host=fakeSyncHost();globalThis.window=host.win;globalThis.document.addEventListener=host.doc.addEventListener;globalThis.document.removeEventListener=host.doc.removeEventListener;globalThis.document.visibilityState='visible';return host}
