test('employee alert badges batch only the current fully editable page and refresh after exact certificate maintenance',async()=>{const calls=[];let saved=false;globalThis.fetch=async(url,opt)=>{const path=String(url);calls.push({url:path,method:opt.method,body:opt.body});if(path.includes('/document-expiries/employees'))return response({items:[{employeeId:'employee',due:saved?0:1,expired:1}]});if(path.includes('/document-expiries?'))return response({...expiryFixture,status:'due',total:saved?0:1,items:saved?[]:[expiryFixture.items[0]]});if(opt.method==='PUT'){saved=true;return response({...documentFixture,version:2})}if(path.endsWith('/documents'))return response({types:[{id:'identity',name:'身份证',enabled:true,version:1}],items:[{...documentFixture,expiresOn:saved?'2030-01-01':'2026-10-29'}]});return response({items:[employee],limit:50,offset:0})};const {root,router}=await mount(EmployeeList,'/stores/A/workforce/employees');assert.ok(button(root,'即将到期 1'));assert.ok(button(root,'已过期 1'));button(root,'即将到期 1').props.onClick();await settle();assert.ok(calls.some(c=>c.url.includes('employeeId=employee')&&c.url.includes('status=due')));const parent=nodes(root,n=>n.tag==='dialog')[0];nodes(parent,n=>n.props?.['aria-label']==='维护证件 · 身份证 · 2026-10-29')[0].props.onClick();await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,2);parent.props.onCancel({preventDefault(){}});await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,2);const child=nodes(root,n=>n.tag==='dialog')[1];nodes(child,n=>n.tag==='input'&&n.props.type==='date')[0].props['onUpdate:modelValue']('2030-01-01');await nodes(child,n=>n.tag==='form')[0].props.onSubmit({preventDefault(){}});await settle();assert.ok(calls.find(c=>c.method==='PUT').url.endsWith('/documents/D'));assert.equal(calls.filter(c=>c.url.includes('/document-expiries/employees')).length,2);assert.equal(calls.filter(c=>c.url.includes('/workforce/employees?')).length,1);nodes(child,n=>n.props?.['aria-label']==='关闭')[0].props.onClick();await settle();assert.match(text(parent),/暂无到期提醒/);nodes(parent,n=>n.props?.['aria-label']==='关闭')[0].props.onClick();await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,0);assert.equal(button(root,'即将到期 1'),undefined);assert.ok(button(root,'已过期 1'));assert.equal(router.currentRoute.value.path,'/stores/A/workforce/employees')})
test('partial employee rows never request or show private document alert counts',async()=>{const urls=[];globalThis.fetch=async url=>{urls.push(String(url));return response({items:[{...employee,editable:false}]})};const {root}=await mount(EmployeeList,'/stores/A/workforce/employees');assert.equal(urls.length,1);assert.equal(nodes(root,n=>n.tag==='button'&&/即将到期|已过期/.test(text(n))).length,0);assert.match(text(root),/仅可查看本店基础资料/)})
test('employee alert batch failure stays visibly unavailable and can be retried',async()=>{let batches=0;globalThis.fetch=async url=>String(url).includes('/document-expiries/employees')?++batches===1?response({code:'WORKFORCE_FORBIDDEN'},403):response({items:[{employeeId:'employee',due:2,expired:0}]}):response({items:[employee]});const {root}=await mount(EmployeeList,'/stores/A/workforce/employees');assert.match(text(root),/证件提醒加载失败/);assert.match(text(root),/暂不可用/);assert.equal(button(root,'即将到期 2'),undefined);button(root,'刷新').props.onClick();await settle();assert.ok(button(root,'即将到期 2'));assert.doesNotMatch(text(root),/加载失败|暂不可用/)})
test('old employee page alert responses cannot replace the next page batch',async()=>{let release;const batches=[];globalThis.fetch=async url=>{const path=String(url),query=new URL(path,'http://local').searchParams;if(path.includes('/document-expiries/employees')){batches.push(query.get('employeeIds').split(','));if(batches.length===1)return new Promise(resolve=>release=()=>resolve(response({items:[{employeeId:'late',due:99,expired:99}]})));return response({items:[{employeeId:'next',due:2,expired:0}]})}return response({items:query.get('offset')==='50'?[{...employee,id:'next',name:'Next'}]:Array.from({length:50},(_,i)=>({...employee,id:'e'+i,name:'Person'+i}))})};const {root}=await mount(EmployeeList,'/stores/A/workforce/employees');button(root,'下一页').props.onClick();await settle();assert.equal(batches[0].length,50);assert.deepEqual(batches[1],['next']);assert.ok(button(root,'即将到期 2'));release();await settle();assert.ok(button(root,'即将到期 2'));assert.doesNotMatch(text(root),/99|Person0/)})
test('document expiry reminders show today separately and filter by window/status with protected store routing',async()=>{const urls=[];globalThis.fetch=async url=>{urls.push(String(url));return response(expiryFixture)};const {root,router}=await mount(DocumentExpiryList,'/stores/A/workforce/document-expiries');assert.match(text(root),/今天到期/);assert.match(text(root),/逾期天数 1/);assert.ok(urls[0].includes('/stores/A/workforce/document-expiries?days=30&status=all'));button(root,'已过期 1').props.onClick();await settle();assert.ok(urls.at(-1).includes('status=expired'));const selects=nodes(root,n=>n.tag==='select');selects[1].props['onUpdate:modelValue'](60);await nodes(root,n=>n.tag==='form')[0].props.onSubmit({preventDefault(){}});await settle();assert.ok(urls.at(-1).includes('days=60'));selects[0].props.onChange({target:{value:'B'}});await settle();assert.equal(router.currentRoute.value.fullPath,'/stores/B/workforce/document-expiries?days=60&status=expired')})
