test('expiry maintenance opens the exact certificate and saving refreshes reminder counts without leaving the page',async()=>{const calls=[];let saved=false;globalThis.fetch=async(url,opt)=>{calls.push({url:String(url),method:opt.method,body:opt.body});if(String(url).includes('/document-expiries'))return response(saved?{...expiryFixture,due:0,expired:1,total:1,items:[expiryFixture.items[1]]}:expiryFixture);if(opt.method==='PUT'){saved=true;return response({...documentFixture,version:2,expiresOn:'2030-01-01'})}return response({types:[{id:'identity',name:'身份证',enabled:true,version:1}],items:[{...documentFixture,expiresOn:saved?'2030-01-01':'2026-10-29'},{...documentFixture,id:'OTHER',typeId:'passport',typeName:'护照'}]})};const {root,router}=await mount(DocumentExpiryList,'/stores/A/workforce/document-expiries');nodes(root,n=>n.props?.['aria-label']==='维护证件 · Alice · 身份证')[0].props.onClick();await settle();const modal=nodes(root,n=>n.tag==='dialog')[0];assert.equal(nodes(modal,n=>n.tag==='form').length,1);assert.doesNotMatch(text(modal),/新增证件/);assert.equal(nodes(modal,n=>n.tag==='option'&&text(n)==='护照').length,0);nodes(modal,n=>n.tag==='input'&&n.props.type==='date')[0].props['onUpdate:modelValue']('2030-01-01');await nodes(modal,n=>n.tag==='form')[0].props.onSubmit({preventDefault(){}});await settle();const write=calls.find(c=>c.method==='PUT');assert.ok(write.url.endsWith('/employees/employee/documents/D'));assert.equal(JSON.parse(write.body).expectedVersion,1);assert.equal(calls.filter(c=>c.url.includes('/document-expiries')).length,2);assert.ok(button(root,'即将到期 0'));assert.equal(router.currentRoute.value.path,'/stores/A/workforce/document-expiries');nodes(modal,n=>n.tag==='button'&&n.props['aria-label']==='关闭')[0].props.onClick();await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,0)})
