test('reminder maintenance cannot close while an upload result is uncertain and retries the original file',async()=>{const writes=[];globalThis.fetch=async(url,opt)=>{if(String(url).includes('/document-expiries'))return response(expiryFixture);if(opt.method==='PUT'){writes.push({url:String(url),body:opt.body});if(writes.length===1)throw Error('offline');return response({...documentFixture,version:2})}return response({types:[{id:'identity',name:'身份证',enabled:true,version:1}],items:[documentFixture]})};const {root}=await mount(DocumentExpiryList,'/stores/A/workforce/document-expiries');nodes(root,n=>n.props?.['aria-label']==='维护证件 · Alice · 身份证')[0].props.onClick();await settle();const modal=nodes(root,n=>n.tag==='dialog')[0];await nodes(modal,n=>n.tag==='input'&&n.props.type==='file')[0].props.onChange({target:{files:[new File(['%PDF-1.7\n'],'test.pdf',{type:'application/pdf'})],value:''}});await settle();modal.props.onCancel({preventDefault(){}});await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,1);assert.equal(nodes(modal,n=>n.props?.['aria-label']==='关闭')[0].props.disabled,true);await button(modal,'重试上传').props.onClick();await settle();assert.equal(writes.filter(w=>!w.url.endsWith('/recognition')).length,2);assert.equal(writes.filter(w=>w.url.endsWith('/recognition')).length,1);assert.equal(writes[0].url,writes[1].url);nodes(modal,n=>n.props?.['aria-label']==='关闭')[0].props.onClick();await settle();assert.equal(nodes(root,n=>n.tag==='dialog').length,0)})
