test('private PDF upload retries the same file command after unknown outcome and never creates a public URL',async()=>{const writes=[];globalThis.fetch=async(url,opt)=>{if(opt.method==='PUT'){writes.push({url:String(url),body:opt.body});if(writes.length===1)throw Error('network');return response({...documentFixture,version:2})}return response({types:[{id:'identity',name:'身份证',enabled:true,version:1}],items:[documentFixture]})};const wrapper={render:()=>h(EmployeeDocuments,{employeeId:'employee'})};const {root}=await mount(wrapper,'/stores/A/workforce/profile');button(root,'编辑').props.onClick();await settle();const input=nodes(root,n=>n.tag==='input'&&n.props.type==='file')[0];await input.props.onChange({target:{files:[new File(['%PDF-1.7\n'],'test.pdf',{type:'application/pdf'})],value:'test.pdf'}});await settle();assert.match(text(root),/上传结果未确定/);assert.equal(writes.length,1);await button(root,'重试上传').props.onClick();await settle();assert.equal(writes[0].url,writes[1].url);assert.equal(writes[0].body.get('expectedVersion'),'1');assert.equal(writes[0].body.get('file').size,9);assert.equal(nodes(root,n=>n.tag==='img').length,0)})
